export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

export class Table {
  constructor() {
    this.map = new Map()
    this.header = false
  }
}
export class ArrayOfTables {
  constructor() {
    this.items = []
  }
}
export class List {
  constructor(items) {
    this.items = items
  }
}

const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(text, lineNo) {
    this.s = text
    this.i = 0
    this.n = lineNo
  }
  fail(msg) {
    throw new ParseError(msg, this.n)
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  // True at the end of the line or at a comment start.
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }

  string(quote) {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      const c = s[this.i]
      if (c === undefined) this.fail('unterminated string')
      if (c === quote) {
        this.i++
        return out
      }
      if (quote === '"' && c === '\\') {
        const e = s[this.i + 1]
        if (e === undefined) this.fail('unterminated string')
        const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          out += simple[e]
          this.i += 2
        } else if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          this.fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(this.i + 1)))
        }
      } else {
        out += c
        this.i++
      }
    }
  }

  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (st === this.i) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      this.ws()
      if (this.s[this.i] !== '.') return parts
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.s[this.i]
    if (this.atEnd() || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { type: 'string', value: this.string('"') }
    if (c === "'") return { type: 'string', value: this.string("'") }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !/[ \t,\]};]/.test(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { type: 'boolean', value: true }
    if (w === 'false') return { type: 'boolean', value: false }
    if (INT.test(w)) return { type: 'integer', value: w.replace(/_/g, '').replace(/^\+/, '') }
    if (FLOAT.test(w)) return { type: 'float', value: Number(w.replace(/_/g, '')) }
    this.fail('invalid value ' + w)
  }

  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return new List(items)
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c !== ']') this.fail('trailing text after a value')
    }
  }

  inline(prefix) {
    this.i++
    const t = new Table()
    this.ws()
    if (this.s[this.i] === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.s[this.i] !== '=') this.fail('expected = in an inline table')
