      const v = this.value([...prefix, ...keys])
      this.assign(t, prefix, keys, v)
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return t
      } else this.fail('trailing text after a value')
    }
  }

  // Walk `keys` (all but the last) from `base`, creating tables on the way.
  walk(base, prefix, keys) {
    let cur = base
    const path = [...prefix]
    for (const k of keys) {
      path.push(k)
      let nx = cur.map.get(k)
      if (nx === undefined) {
        nx = new Table()
        cur.map.set(k, nx)
      }
      if (nx instanceof ArrayOfTables) nx = nx.items[nx.items.length - 1]
      if (!(nx instanceof Table)) this.fail(`${path.join('.')} is not a table`)
      cur = nx
    }
    return cur
  }

  assign(base, prefix, keys, v) {
    const t = this.walk(base, prefix, keys.slice(0, -1))
    const last = keys[keys.length - 1]
    if (t.map.has(last)) this.fail(`key ${[...prefix, ...keys].join('.')} is defined twice`)
    t.map.set(last, v)
  }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let current = root
  lines.forEach((text, idx) => {
    const p = new LineParser(text, idx + 1)
    p.ws()
    const c = text[p.i]
    if (c === undefined || c === '#' || c === ';') return
    if (c === '[') {
      const isArr = text[p.i + 1] === '['
      p.i += isArr ? 2 : 1
      p.ws()
      const keys = p.dotted()
      p.ws()
      const close = isArr ? ']]' : ']'
      if (text.startsWith(close, p.i)) p.i += close.length
      else if (p.atEnd()) p.fail('unterminated table header')
      else p.fail('trailing text after a table header')
      p.ws()
      if (!p.atEnd()) p.fail('trailing text after a table header')
      const parent = p.walk(root, [], keys.slice(0, -1))
      const last = keys[keys.length - 1]
      const path = keys.join('.')
      const ex = parent.map.get(last)
      if (isArr) {
        if (ex === undefined) {
          const a = new ArrayOfTables()
          parent.map.set(last, a)
          current = new Table()
          a.items.push(current)
        } else if (ex instanceof ArrayOfTables) {
          current = new Table()
          ex.items.push(current)
        } else p.fail(`${path} is not an array of tables`)
      } else if (ex === undefined) {
        current = new Table()
        current.header = true
        parent.map.set(last, current)
      } else if (ex instanceof Table) {
        if (ex.header) p.fail(`table ${path} is defined twice`)
        ex.header = true
        current = ex
      } else p.fail(`${path} is not a table`)
      return
    }
    const keys = p.dotted()
    p.ws()
    if (p.s[p.i] !== '=') p.fail('expected key = value')
    p.i++
    const pre = pathOf(root, current)
    const v = p.value([...pre, ...keys])
    p.assign(current, pre, keys, v)
    p.ws()
    if (!p.atEnd()) p.fail('trailing text after a value')
  })
  return root
}

// Path of names from the root to `target` (arrays of tables contribute their name only).
function pathOf(root, target) {
  if (root === target) return []
  const find = (t, path) => {
    for (const [k, v] of t.map) {
      const cands = v instanceof ArrayOfTables ? v.items : [v]
      for (const c of cands) {
        if (c === target) return [...path, k]
        if (c instanceof Table) {
          const r = find(c, [...path, k])
          if (r) return r
        }
      }
    }
    return null
  }
  return find(root, [])
}
